'use client';

// TEMPORARY — screenshot harness for the Production Dashboard redesign. Not to
// be committed. Seeds the query cache from fixtures generated by the real
// section services over a synthetic pglite database, so the authed page can be
// rendered without a login. Delete this folder after the screenshots.

import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { qk } from '@/lib/queryKeys';
import { ProductionDashboard } from '@/components/production/ProductionDashboard';
import fixtures from './fixtures.json';

export default function Page() {
  const qc = useQueryClient();
  useState(() => {
    qc.setQueryDefaults(['productionOverview'], { gcTime: Infinity, staleTime: Infinity });
    const mode = typeof window !== 'undefined' ? new URLSearchParams(window.location.search).get('mode') : null;
    for (const [key, value] of Object.entries(fixtures.overview)) {
      const [period, branch] = key.split('|');
      qc.setQueryData(qk.productionOverview(branch === 'all' ? null : branch, period), value);
    }
    for (const [key, value] of Object.entries(fixtures.sections)) {
      const [section, period, branch] = key.split('|') as [string, string, string];
      // ?mode=states: one section failed, one empty, to show the states.
      if (mode === 'states' && section === 'repaired-stock') continue;
      let v: unknown = value;
      if (mode === 'states' && section === 'return-stock') {
        const s = value as { kpis: Record<string, number | null>; series: { returned: number }[] };
        v = { ...s, kpis: { ...s.kpis, returned: 0, returnRate: null }, series: s.series.map((p) => ({ ...p, returned: 0 })) };
      }
      qc.setQueryData(qk.productionDashboardSection(section, period!, branch === 'all' ? null : branch), v);
    }
    if (mode === 'states') {
      for (const period of ['today', 'week', 'month']) {
        for (const b of [null, fixtures.focusBranchId]) {
          const key = qk.productionDashboardSection('repaired-stock', period, b);
          qc.getQueryCache().build(qc, { queryKey: key }).setState({ status: 'error', error: new Error('Request failed with 502 Bad Gateway'), fetchStatus: 'idle', data: undefined });
        }
      }
    }
    return null;
  });
  return (
    <div className="min-h-screen bg-background p-4 sm:p-6">
      <ProductionDashboard />
    </div>
  );
}
